<script setup>
import {computed} from 'vue'
import ScienceVisual from './ScienceVisual.vue'
import SceneVisualEditor from './SceneVisualEditor.vue'
const props=defineProps({slide:Object,editable:Boolean,preview:Boolean})
const d=computed(()=>props.slide.scientific)
const free=computed(()=>!['graph','chart','table','figure','picture','diagram','scientific'].some(k=>props.slide[k]))
function add(kind){props.slide.scientific=kind==='thin_lens'?{kind,title:'凸透镜成像',focal_length_cm:10,object_distance_cm:30,object_height_cm:3}:kind==='molecule'?{kind,title:'乙醇的羟基',smiles:'CCO',highlight_group:'hydroxyl'}:kind==='cell'?{kind,title:'植物细胞结构',cell_type:'plant',visible_parts:['cell_wall','cell_membrane','cytoplasm','nucleus','mitochondrion','chloroplast','vacuole'],highlight_parts:['chloroplast']}:kind==='triangle'?{kind,title:'三角形的边长关系',sides:[3,4,5]}:kind==='forces'?{kind,title:'物体的受力',object:'静止木块',unit:'N',equilibrium:true,forces:[{label:'重力',x:0,y:-10},{label:'支持力',x:0,y:10}]}:{kind,title:'理想电路（示例）',voltage:6,resistances:[10,20],connection:'series',closed:true}}
const extended=computed(()=>['thin_lens','molecule','cell','scene'].includes(d.value?.kind))
function addScene(){props.slide.scientific={kind:'scene',title:'路径与位置（教学示意）',scene:{duration_ms:3000,objects:[{id:'route',type:'path',points:[[.2,.5],[.5,.3],[.8,.5]],color:'#60758a'},{id:'particle',type:'ellipse',x:.2,y:.5,width:.04,height:.06,color:'#bc582b',fill:'#bc582b'},{id:'label',type:'text',x:.5,y:.82,text:'观察路径与位置',font_size:28,color:'#18324c'}],actions:[{object:'particle',op:'follow_path',path:'route',start_ms:0,duration_ms:2500}]}}}
const parts={cell_wall:'细胞壁',cell_membrane:'细胞膜',cytoplasm:'细胞质',nucleus:'细胞核',mitochondrion:'线粒体',chloroplast:'叶绿体',vacuole:'中央液泡'}
function changeCell(){if(d.value.cell_type==='animal'){d.value.visible_parts=d.value.visible_parts.filter(p=>!['cell_wall','chloroplast','vacuole'].includes(p));d.value.highlight_parts=d.value.highlight_parts.filter(p=>d.value.visible_parts.includes(p));if(!d.value.highlight_parts.length)delete d.value.animation}}
function changeParts(){d.value.highlight_parts=d.value.highlight_parts.filter(p=>d.value.visible_parts.includes(p));if(!d.value.highlight_parts.length)delete d.value.animation}
function toggleAnimation(event){if(event.target.checked)d.value.animation={param:d.value.kind==='thin_lens'?'object_distance_cm':'highlight',to:d.value.kind==='thin_lens'?15:1,duration_ms:2000};else delete d.value.animation}
const triangle=computed(()=>{const [a,b,c]=d.value?.sides||[];if(![a,b,c].every(n=>Number.isFinite(n)&&n>0)||Math.min(a+b-c,a+c-b,b+c-a)<=0)return null;const cx=(a*a+b*b-c*c)/(2*a),cy=Math.sqrt(b*b-cx*cx),scale=Math.min(270/(Math.max(a,cx)-Math.min(0,cx)),145/cy),ox=30-Math.min(0,cx)*scale;return [[ox,185],[ox+a*scale,185],[ox+cx*scale,185-cy*scale]]})
const resultant=computed(()=>{const f=d.value?.forces||[];return {x:f.reduce((s,v)=>s+Number(v.x),0),y:f.reduce((s,v)=>s+Number(v.y),0)}})
const forces=computed(()=>{const f=d.value?.forces||[],max=Math.max(...f.map(v=>Math.hypot(v.x,v.y)));if(!max||!Number.isFinite(max))return [];return f.map(v=>({...v,ex:160+v.x/max*70,ey:130-v.y/max*70,magnitude:Math.hypot(v.x,v.y)}))})
const circuit=computed(()=>{const v=d.value;if(!v?.resistances?.length||v.resistances.some(r=>!Number.isFinite(r)||r<=0)||!Number.isFinite(v.voltage))return null;const r=v.connection==='series'?v.resistances.reduce((a,b)=>a+b,0):1/v.resistances.reduce((a,b)=>a+1/b,0);return {r,i:v.closed===false?0:v.voltage/r}})
const n=value=>Number(value.toPrecision(5))
</script>
<template>
 <div v-if="preview&&d" class="scientific-preview">
  <h3>{{d.title}}</h3>
  <ScienceVisual v-if="extended" :diagram="d"/>
  <template v-if="d.kind==='triangle'"><svg v-if="triangle" viewBox="0 0 330 220" role="img" aria-label="按边长比例绘制的三角形"><polygon :points="triangle.map(p=>p.join(',')).join(' ')" fill="none" stroke="currentColor" stroke-width="2"/><text v-for="(p,i) in triangle" :key="i" :x="p[0]" :y="p[1]+18">{{'ABC'[i]}}</text></svg><p v-else role="alert">三条边不能构成三角形</p><p>AB={{d.sides[0]}}，AC={{d.sides[1]}}，BC={{d.sides[2]}}</p></template>
  <template v-else-if="d.kind==='forces'"><p>研究对象：{{d.object}}</p><svg viewBox="0 0 330 240" role="img" aria-label="由力的分量计算方向和长度"><circle cx="160" cy="130" r="5" fill="currentColor"/><g v-for="(f,i) in forces" :key="i"><line x1="160" y1="130" :x2="f.ex" :y2="f.ey" stroke="currentColor" stroke-width="2"/><path :d="`M ${f.ex-6} ${f.ey+9} L ${f.ex} ${f.ey} L ${f.ex+6} ${f.ey+9}`" :transform="`rotate(${Math.atan2(f.y,f.x)*-180/Math.PI-90},${f.ex},${f.ey})`" fill="none" stroke="currentColor"/><text :x="f.ex-40" :y="f.ey<130?f.ey-12:f.ey+25">{{f.label}} {{n(f.magnitude)}} N</text></g></svg><p>合力 ({{n(resultant.x)}}, {{n(resultant.y)}}) N</p><p v-if="d.equilibrium&&Math.hypot(resultant.x,resultant.y)>0.000001" role="alert">合力不为零，请核对平衡条件。</p></template>
  <template v-else-if="d.kind==='circuit'"><svg viewBox="0 0 330 230" role="img" :aria-label="d.connection==='series'?'串联电阻电路':'并联电阻电路'"><path d="M 150 40 H 35 V 75 M 295 180 V 40 H 174" fill="none" stroke="currentColor" stroke-width="2"/><path class="scientific-switch" :d="d.closed===false?'M35 75 V98 M35 128 V180 M35 98 L53 117':'M35 75 V180'" fill="none" stroke="currentColor" stroke-width="2"/><path d="M150 24 V56 M174 30 V50" fill="none" stroke="currentColor" stroke-width="3"/><line v-if="d.connection==='series'" x1="35" x2="295" y1="180" y2="180" stroke="currentColor"/><g v-for="(r,i) in d.resistances" :key="i"><line v-if="d.connection==='parallel'" x1="35" x2="295" :y1="40+140*(i+1)/d.resistances.length" :y2="40+140*(i+1)/d.resistances.length" stroke="currentColor"/><rect :x="d.connection==='series'?55+i*80:140" :y="d.connection==='series'?170:30+140*(i+1)/d.resistances.length" width="45" height="20" fill="white" stroke="currentColor"/><text :x="d.connection==='series'?50+i*80:200" :y="d.connection==='series'?210:44+140*(i+1)/d.resistances.length">R{{i+1}}={{r}} Ω</text></g></svg><p v-if="circuit">{{d.voltage}} V · 总电阻 {{n(circuit.r)}} Ω · 总电流 {{n(circuit.i)}} A</p><p>理想电路模型 · {{d.closed===false?'开关断开':'闭合'}}</p></template>
 </div>
 <section v-else-if="!preview" class="scientific-editor">
  <div v-if="editable&&free" class="evidence-actions"><button type="button" @click="addScene">＋ 通用图形动画</button><button type="button" @click="add('triangle')">＋ 三边几何图</button><button type="button" @click="add('forces')">＋ 受力图</button><button type="button" @click="add('circuit')">＋ 串并联电路</button><button type="button" @click="add('thin_lens')">＋ 凸透镜成像</button><button type="button" @click="add('molecule')">＋ 分子结构</button><button type="button" @click="add('cell')">＋ 细胞结构</button></div>
  <template v-if="d"><h4>专业图示参数</h4><label>教学用途/标题<input v-model="d.title" :readonly="!editable" maxlength="60"></label>
   <SceneVisualEditor v-if="d.kind==='scene'" :scene="d.scene" :editable="editable"/>
   <template v-if="d.kind==='thin_lens'"><label>焦距 / cm<input type="number" min="1" max="100" step="any" v-model.number="d.focal_length_cm" :readonly="!editable"></label><label>物距 / cm<input type="number" min="1" max="300" step="any" v-model.number="d.object_distance_cm" :readonly="!editable"></label><label>物高 / cm<input type="number" min="0.1" max="10" step="any" v-model.number="d.object_height_cm" :readonly="!editable"></label><p>理想薄透镜近轴模型，像距与放大率由程序计算。</p></template>
   <template v-if="d.kind==='molecule'"><label>结构 SMILES<input v-model="d.smiles" :readonly="!editable" maxlength="300"></label><label>高亮官能团<select v-model="d.highlight_group" :disabled="!editable" @change="d.highlight_group==='none'&&delete d.animation"><option value="none">无</option><option value="hydroxyl">羟基</option><option value="carboxyl">羧基</option><option value="amino">氨基</option><option value="carbonyl">羰基</option><option value="double_bond">碳碳双键</option></select></label><p>请输入有依据的结构；名称与结构对应关系需核对。仅二维结构展示，不表示反应已验证。</p></template>
   <template v-if="d.kind==='cell'"><label>细胞类型<select v-model="d.cell_type" :disabled="!editable" @change="changeCell"><option value="plant">植物细胞</option><option value="animal">动物细胞</option></select></label><fieldset><legend>显示结构</legend><label v-for="(label,key) in parts" :key="key" v-show="d.cell_type==='plant'||!['cell_wall','chloroplast','vacuole'].includes(key)"><input type="checkbox" v-model="d.visible_parts" :value="key" :disabled="!editable" @change="changeParts">{{label}}</label></fieldset><fieldset><legend>高亮结构</legend><label v-for="key in d.visible_parts" :key="key"><input type="checkbox" v-model="d.highlight_parts" :value="key" :disabled="!editable" @change="!d.highlight_parts.length&&delete d.animation">{{parts[key]}}</label></fieldset><p>典型细胞简化示意，非真实比例或显微照片。</p></template>
   <template v-if="extended"><template v-if="d.kind!=='scene'"><label><input type="checkbox" :checked="!!d.animation" :disabled="!editable||d.kind==='molecule'&&(!d.highlight_group||d.highlight_group==='none')||d.kind==='cell'&&!d.highlight_parts.length" @change="toggleAnimation">导出动态演示 GIF</label><template v-if="d.animation"><label v-if="d.kind==='thin_lens'">终点物距 / cm<input type="number" min="1" max="300" step="any" v-model.number="d.animation.to" :readonly="!editable"></label><label>时长 / 毫秒<input type="number" min="1000" max="8000" v-model.number="d.animation.duration_ms" :readonly="!editable"></label><p>预览与PPT均为循环GIF，修改后重新绘制。</p></template></template><ScienceVisual :diagram="d"/></template>
   <template v-if="d.kind==='triangle'"><label v-for="(_,i) in d.sides" :key="i">{{['AB','AC','BC'][i]}} 边长<input type="number" step="any" v-model.number="d.sides[i]" :readonly="!editable"></label><p>按真实比例构造三角形，边长单位须在正文中说明。</p></template>
   <template v-if="d.kind==='forces'"><label>研究对象<input v-model="d.object" :readonly="!editable" maxlength="24"></label><label><input type="checkbox" v-model="d.equilibrium" :disabled="!editable">平衡状态（合力须为零）</label><div v-for="(f,i) in d.forces" :key="i" class="force-fields"><label>力名称<input v-model="f.label" :readonly="!editable" maxlength="20"></label><label>x分量/N<input type="number" step="any" v-model.number="f.x" :readonly="!editable"></label><label>y分量/N<input type="number" step="any" v-model.number="f.y" :readonly="!editable"></label></div><p>x向右、y向上；只填写作用于该物体的力。</p><div v-if="editable"><button type="button" :disabled="d.forces.length>=4" @click="d.forces.push({label:'',x:1,y:0})">加一个力</button><button type="button" :disabled="d.forces.length<=1" @click="d.forces.pop()">删除末项</button></div></template>
   <template v-if="d.kind==='circuit'"><label>连接<select v-model="d.connection" :disabled="!editable"><option value="series">串联</option><option value="parallel">并联</option></select></label><label>电压/V<input type="number" step="any" v-model.number="d.voltage" :readonly="!editable"></label><label v-for="(_,i) in d.resistances" :key="i">R{{i+1}} / Ω<input type="number" step="any" v-model.number="d.resistances[i]" :readonly="!editable"></label><label><input type="checkbox" v-model="d.closed" :disabled="!editable">开关闭合</label><div v-if="editable"><button type="button" :disabled="d.resistances.length>=3" @click="d.resistances.push(10)">加电阻</button><button type="button" :disabled="d.resistances.length<=1" @click="d.resistances.pop()">删除末项</button></div><p>仅理想电源、导线和电阻模型，数值自动计算。</p></template>
   <button v-if="editable" type="button" @click="slide.scientific=null">移除专业图示</button>
  </template>
 </section>
</template>
<style scoped>
.scientific-preview svg{display:block;width:100%;max-height:260px}.scientific-preview text{font-size:12px;fill:currentColor}.scientific-preview p,.scientific-editor p{font-size:12px}.scientific-editor{margin-top:14px}.scientific-editor label{margin-top:10px}.force-fields{display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px}.evidence-actions{display:flex;flex-wrap:wrap;gap:8px}.evidence-actions button{font-size:11px}
</style>
